# codec plugin

/*
Codec Plugin 可以支持在 Codec 中自定义编码解码，自定义 Bypass 与字符串处理函数

函数定义非常简单

func(i: string) string
*/

handle = func(origin /*string*/) {
    origin = str.TrimSpace(origin)
    origin = str.ToLower(origin)
    if str.HasPrefix(origin, "string.fromcharcode(") {
        origin = origin[21:]
        if str.HasSuffix(origin, ")") {
            origin = origin[:len(origin)-1]
        }
    }
    result = ""
    for _, a = range str.Split(origin, ",") {
        a = str.TrimSpace(a)
        i, err = atoi(a)
        if err != nil {
            continue 
        }
        result += chr(i)
    }

    return result
}
